insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-10-14','verbeterd','Acties','Je ziet nu waarom een actie niet af te vinken is',
   'Kun je een actie niet zelf afronden, bijvoorbeeld omdat hij vanzelf sluit zodra het formulier of projectbezoek klaar is, dan zie je nu die uitleg in plaats van een onduidelijke foutmelding.'),
  ('2026-10-14','opgelost','Algemeen','Een reeks kleine fouten opgelost',
   'Het vinkje "alles selecteren" in lijsten werkt weer, bestanden met een streepje of bijzonder teken in de naam openen weer, en de handtekening van een medewerker is weer zichtbaar. Snel typen in een omschrijving in de calculatie geeft geen foutscherm meer.');
